    @EventHandler( payloadType=CreateCustomerEvent.class )
    public void handle( CreateCustomerEvent event) {
	    LOGGER.info("handling CreateCustomerEvent - " + event );
	    Customer entity = new Customer();
            entity.setCustomerId( event.getCustomerId() );
            entity.setFirstName( event.getFirstName() );
            entity.setLastName( event.getLastName() );
            entity.setLegalName( event.getLegalName() );
            entity.setDateOfBirth( event.getDateOfBirth() );
            entity.setTaxId( event.getTaxId() );
            entity.setEmail( event.getEmail() );
            entity.setPhone( event.getPhone() );
            entity.setAddress( event.getAddress() );
            entity.setCustomerType( event.getCustomerType() );
            entity.setRiskRating( event.getRiskRating() );
            entity.setKycStatus( event.getKycStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllCustomer( entity );
    }

